import {ENEMY_ABILITIES,ENEMY_LOADOUTS} from '../data/enemyAbilities.js';
import {ENEMY_SETS} from '../data/enemySets.js';
import {canPlayMission,lockedMessage} from '../core/CampaignAccess.js';
import {renderPowerups} from './PowerupMenu.js';
import {selectedPower} from '../data/powerups.js';
import {TRACKS} from '../audio/MusicScore.js';
import {NarrativeUI} from './NarrativeUI.js';
import {appearance} from '../data/appearance.js';
import {CHARACTERS,DIFFICULTIES} from '../data/characters.js';
import {CAMPAIGN} from '../data/missions.js';
import {linesFor,VOICE_LINES} from '../data/voices.js';
import {PROP_SKINS,ENV_SKINS,DETAIL_SKINS,SKIN_NAMES} from '../data/skins.js';
import {AVAILABLE_MISSIONS} from '../data/campaign.js';
import {ENEMY_TYPES} from '../data/enemies.js';
import {ITEMS} from '../characters/EquipmentLoadout.js';
const escapeHtml=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class UIManager{
 constructor(app){this.app=app;this.narrative=new NarrativeUI(app);this.dialog=document.querySelector('#menu');this.content=document.querySelector('#menu-content');this.voiceCharacter='click';this.selectedEquip='click';this.tab='journal';this.bus=app.bus;this.bus.on('zone:loading',name=>{let el=document.querySelector('#zone-loading');if(!el){el=document.createElement('div');el.id='zone-loading';el.className='zone-loading';el.setAttribute('role','status');document.querySelector('.game-frame').append(el);}el.textContent='ENTRANDO · '+name;el.classList.remove('hidden');});this.bus.on('zone:loaded',()=>document.querySelector('#zone-loading')?.classList.add('hidden'));this.bus.on('hud:update',s=>this.hud(s));this.bus.on('voice:line',line=>{const el=document.querySelector('#subtitle');el.classList.remove('hidden');el.querySelector('b').textContent=line.name;el.querySelector('span').textContent=line.text;});this.bus.on('voice:clear',()=>document.querySelector('#subtitle').classList.add('hidden'));this.bus.on('toast',text=>this.toast(text));this.bus.on('special:activated',({name,ability})=>{const el=document.querySelector('#cutin');el.querySelector('strong').textContent=name.toUpperCase();el.querySelector('span').textContent=ability;el.classList.remove('hidden');clearTimeout(this.cutinTimer);this.cutinTimer=setTimeout(()=>el.classList.add('hidden'),1000);});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>this.render(b.dataset.tab));document.querySelector('#close-menu').onclick=()=>this.close();this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.close();});this.dialog.addEventListener('click',e=>{if(e.target===this.dialog){const r=this.dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)this.close();}});window.speechSynthesis?.addEventListener('voiceschanged',()=>{if(this.dialog.open&&this.tab==='voices')this.render('voices');});}
 toast(text){const el=document.querySelector('#game-toast');el.textContent=text;el.classList.remove('hidden');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>el.classList.add('hidden'),3400);}
 hud(scene){const p=scene.player;if(!p)return;const special=document.querySelector('[data-control="special"]');special?.setAttribute?.('aria-label','Mossa speciale: '+(p.data.child?'Scatto':selectedPower(this.app.settings,p.id)?.name||p.data.special));const h=document.querySelector('#player-hud');h.innerHTML=`<div class="hud-person"><div class="hud-portrait"><div class="mini-sprite" style="${this.portraitStyle(p)}"></div></div><div><b>${p.data.name.toUpperCase()} <small class="hud-health-value">${Math.ceil(p.hp)} / ${p.data.hp}</small></b><div class="bar hp"><i style="width:${p.hp/p.data.hp*100}%"></i></div><div class="bar sp"><i style="width:${p.special}%"></i></div></div></div>`;document.querySelector('#cash-hud').textContent='€ '+this.app.progress.cash.toLocaleString('it-IT');document.querySelector('#chapter-pill').textContent=`0${scene.mission.state.index+1} / ${scene.mission.config.short}`;document.querySelector('#objective-title').textContent=scene.mission.config.name;document.querySelector('#objective-copy').textContent=scene.mission.config.description;document.querySelector('#objectives').innerHTML=scene.mission.config.objectives.map(([key,text])=>`<div class="objective ${scene.mission.complete(key)?'done':''}">${text}${scene.mission.target(key)!==undefined?` (${scene.mission.state[key]||0}/${scene.mission.target(key)})`:''}</div>`).join('');const next=scene.mission.config.objectives.find(([k])=>!scene.mission.complete(k));document.querySelector('#quick-journal').textContent=scene.isHideout?'⌂ Esplora le postazioni · A parla · tavolo centrale: missioni':scene.mission.state.exit?'✓ Capitolo completato':next?'◇ '+next[1]:'✓ Obiettivi completati · raggiungi l’uscita';const cards=document.querySelector('#team-cards');const state=scene.party.map(a=>`${a.id}-${Math.ceil(a.hp)}-${a===p}-${a.hidden}`).join();if(cards.dataset.state!==state){cards.dataset.state=state;cards.innerHTML=scene.party.map(a=>`<button class="team-card ${a===p?'active':''}" data-person="${a.id}" style="width:100%;text-align:left"><i class="team-dot" style="background:${a.data.color}"></i><div><b>${a.data.name}</b><span>${a.hidden?'A bordo · prosegui con Andy':a.ko?'KO · avvicinati e premi A per rianimare':Math.ceil(a.hp)+' HP · '+a.data.role}</span></div></button>`).join('');cards.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{if(scene.activeMission)scene.switchCharacter(b.dataset.person);});}}
 open(tab='journal'){if(this.dialog.open){this.render(tab);return;}this.app.audio.stop();this.app.input.enabled=false;this.app.input.clear();this.app.scene?.scene.pause();this.dialog.showModal();this.render(tab);}
 close(){this.app.audio.unlock();this.app.music?.stopPreview();this.app.audio.stop();this.dialog.close();if(this.app.playing){this.app.scene?.scene.resume();this.app.input.enabled=!!this.app.scene?.activeMission;}}
 render(tab){this.tab=tab;document.querySelector('#menu-title').textContent={journal:'Il diario',characters:'La banda',equipment:'Preparati al colpo',voices:'Le voci della banda',settings:'Opzioni',powerups:'Potenziamenti',enemies:'Conosci gli avversari',world:'Il mondo della banda'}[tab];document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));this[tab]();}
 portraitStyle(p){const a=appearance(p.id,{children:!!p.data.child,elegant:p.data.skin==='click-suit'});return `background-image:url('assets/${a.texture}-atlas.png');background-size:400% ${a.rows*100}%;background-position:0 ${a.row*100/(a.rows-1)}%;`;}
 journal(){
  const completed=this.app.save.completed(),scene=this.app.scene;
  this.content.innerHTML=`${this.app.playing&&scene?`<div class="voice-note"><b>OBIETTIVO ATTUALE · ${scene.mission.config.name}</b><br>${scene.mission.config.description}<br>${scene.mission.config.objectives.map(([k,t])=>(scene.mission.complete(k)?'✓ ':'◇ ')+t).join('<br>')}</div>`:''}<p>Dieci missioni giocabili, trentuno capitoli. Dalla Grecia ai diamanti, fino a Roma e al compleanno di Click. ${this.app.settings?.unlockAllMissions===true?'Sblocco libero attivo: scegli qualsiasi missione.':'Completa una missione per sbloccare la successiva.'}</p>${CAMPAIGN.map(([name,place,party],i)=>`<div class="campaign-row ${canPlayMission(i+1,completed,this.app.settings?.unlockAllMissions)?'current':''}"><strong>${String(i+1).padStart(2,'0')}</strong><div><b>${name}</b><p>${place} · ${party}</p></div>${canPlayMission(i+1,completed,this.app.settings?.unlockAllMissions)?`<button class="badge available" data-mission="${i+1}">${completed.includes(i+1)?'✓ RIGIOCA':'GIOCA ↗'}</button>`:`<button class="badge" data-locked-mission="${i+1}" aria-disabled="true">🔒 BLOCCATA</button>`}</div>`).join('')}<p id="campaign-lock-message" role="status" aria-live="polite"></p><p class="notice">${this.app.settings?.unlockAllMissions===true?'Sblocca tutte le missioni è attivo nelle Opzioni. Disattivalo per tornare allo sblocco basato sui tuoi progressi.':'Le missioni si sbloccano completando tutte le precedenti.'} Dopo aver completato la campagna puoi rigiocarle in qualsiasi ordine. Avviare un’altra missione sostituisce il checkpoint corrente; le missioni completate e gli audio restano conservati.</p>`;
  this.content.querySelectorAll('[data-locked-mission]').forEach(b=>b.onclick=()=>{this.content.querySelector('#campaign-lock-message').textContent=lockedMessage(Number(b.dataset.lockedMission),completed);});
  this.content.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{this.close();this.app.start(false,Number(b.dataset.mission));});
 }
 enemies(){
  const difficulty=DIFFICULTIES[this.app.playing?this.app.progress.difficulty:document.querySelector('#difficulty')?.value]||DIFFICULTIES.normal;
  const badge={visor:'VIS',pack:'EXP',shield:'BLU',medic:'✚',blades:'II',drone:'DRN',command:'★',hammer:'HAM',diamond:'◇'};
  this.content.innerHTML=`<p><b>${difficulty.name}: ${difficulty.abilities} abilità per nemico${difficulty.simultaneous===2?', due insieme in ogni attacco speciale':''}.</b> Le mosse ruotano nell’ordine mostrato. Le aree colorate anticipano l’impatto: esci dal segnale oppure interrompi il nemico. Facile: 1 abilità · Medio: 2 · Difficile: 3 · Extreme: 3, combinate a coppie.</p><div class="enemy-roster">${Object.entries(ENEMY_TYPES).map(([id,e])=>`<article class="enemy-card"><div class="enemy-look"><i class="enemy-sprite" style="background-image:url('assets/${e.texture||'enemies'}-atlas.png');background-size:400% ${e.texture?300:400}%;background-position:0 ${e.row*100/(e.texture?2:3)}%;${e.tint?'filter:sepia(.3) saturate(1.4);':''}"></i>${e.gear?`<b class="enemy-role-badge" style="color:${e.color}">${badge[e.gear]}</b>`:''}</div><div><span class="eyebrow">${e.boss||id==='captain'?'CAPO MISSIONE':e.military?'UNITÀ MILITARE':'RIVALI & SICUREZZA'}</span><h3>${e.name}</h3><p>${e.description}</p><div class="enemy-ability-list">${ENEMY_LOADOUTS[id].map((key,i)=>`<span class="${i>=difficulty.abilities?'inactive':''}">${i+1}. ${ENEMY_ABILITIES[key].name}${i>=difficulty.abilities?' · livello superiore':''}</span>`).join('')}</div><small>Salute ${e.hp} · Velocità ${e.speed} · Danno base ${e.damage}</small></div></article>`).join('')}</div><h3>CHI INCONTRERAI</h3><div class="enemy-mission-sets">${Object.entries(ENEMY_SETS).map(([id,set])=>`<article><span class="eyebrow">MISSIONE ${String(id).padStart(2,'0')}</span><h3>${set.name}</h3><p>${set.troops.map(k=>ENEMY_TYPES[k].name).join(' · ')}</p><b>Capo: ${ENEMY_TYPES[set.boss].name}</b>${set.note?`<p>${set.note}</p>`:''}</article>`).join('')}</div><p class="notice">La difficoltà aumenta anche numero, salute e danni. I capi non vengono duplicati: ricevono una scorta. Restano anche Caposquadra e Supervisore negli scontri intermedi, gli attacchi a metà vita dei capi e le due cariche dell’alligatore. Cura e richiamo aiutano soltanto i nemici vivi: nessuna resurrezione degli avversari già sconfitti.</p>`;
 }
 characters(){this.content.innerHTML=`<div class="roster">${CHARACTERS.map(c=>`<article class="roster-card"><span class="eyebrow">GIOCABILE · CAMPAGNA 01–10</span><h3>${c.name} <small style="font:12px Arial">${c.full!==c.name?c.full:''}</small></h3><p>${c.description}</p><b>${c.special}</b>${c.hp?`<p>Salute ${c.hp} · Forza ${c.strength} · Difesa ${c.defense}<br>Velocità ${c.speed} · Intelligenza ${c.intelligence}</p>`:''}</article>`).join('')}</div>`;}
 world(){
  const cards=(names,texture,rows)=>names.map((key,i)=>`<article class="skin-card"><i class="world-sprite" style="background-image:url('assets/${texture}-atlas.png');background-size:400% ${rows*100}%;background-position:${i%4*100/3}% ${Math.floor(i/4)*100/(rows-1)}%"></i><b>${SKIN_NAMES[key]}</b></article>`).join('');
  this.content.innerHTML=`<p>Auto, casse, oggetti e ambienti hanno ora le proprie skin. Le icone sopra gli oggetti indicano dove puoi interagire con A / J.</p><div class="skin-grid">${cards(PROP_SKINS,'props',4)}${cards(ENV_SKINS,'environment',2)}${cards(DETAIL_SKINS,'details',4)}</div><p class="notice">Nella villa puoi esplorare salone, camera, studio e galleria. I mobili hanno ingombri fisici; i punti di interesse restano raggiungibili.</p>`;
 }
 powerups(){renderPowerups(this.app,this.content);}
 equipment(){const s=this.app.scene;if(s?.isHideout){this.content.innerHTML='<div class="empty-state">Nel covo puoi esplorare e parlare con la banda. Apri Potenziamenti per scegliere le varianti delle speciali. Prepara gli altri oggetti dopo aver avviato una missione: il checkpoint della campagna resta conservato.</div>';return;}if(s?.mission.mission.children){this.content.innerHTML='<div class="empty-state">Nel prologo i tre fratelli esplorano e fuggono insieme. Usa J per esaminare, Q per cambiare fratello e K per scattare.</div>';return;}if(!s?.party){this.content.innerHTML='<div class="empty-state">Entra in missione per preparare l’equipaggiamento della squadra.</div>';return;}const p=s.party.find(p=>p.id===this.selectedEquip)||s.player;this.content.innerHTML=`<div class="voice-controls"><label>Personaggio <select id="equip-person">${s.party.map(a=>`<option value="${a.id}" ${a===p?'selected':''}>${a.data.name}</option>`).join('')}</select></label></div><p>Forza <b>${p.stats.strength}</b> · Difesa <b>${p.stats.defense}</b> · Velocità <b>${p.stats.speed}</b> · Speciale <b>Lv. ${p.stats.specialLevel}</b></p>${['ARMA','SCUDO','CAPPELLO','SCARPE','GIOIELLO'].map(slot=>`<div class="setting-row"><b>${slot==='ARMA'?'ARMA / ATTREZZO':slot}</b><span>${ITEMS.find(i=>i.id===p.loadout.slots[slot])?.name||'Nessun oggetto'}</span></div>`).join('')}<p><b>NELLO ZAINO</b></p>${ITEMS.filter(i=>this.app.progress.inventory.includes(i.id)).map(i=>`<div class="equip-item"><div><b>${i.name}</b><p>${i.description}</p></div><button class="small-btn" data-equip="${i.id}">${p.loadout.slots[i.slot]===i.id?'Rimuovi':'Equipaggia'}</button></div>`).join('')}<p class="notice">Gli oggetti sono disponibili per i personaggi della squadra. Gli equipaggiamenti vengono conservati al prossimo checkpoint.</p>`;document.querySelector('#equip-person').onchange=e=>{this.selectedEquip=e.target.value;this.equipment();};this.content.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{p.loadout.equip(b.dataset.equip);this.app.progress.equipment[p.id]={...p.loadout.slots};this.equipment();});}
 voices(){const person=this.voiceCharacter,voices=(window.speechSynthesis?.getVoices()||[]).filter(v=>/^it/i.test(v.lang)),selected=this.app.settings.voices[person]||'';this.content.innerHTML=`<div class="voice-note"><b>Prima gli audio, poi la voce del browser.</b><br>Carica una registrazione della singola battuta. Dove manca, parla il browser. I file restano su questo dispositivo e non creano automaticamente un clone vocale.</div><div class="voice-controls"><label>Personaggio <select id="voice-person">${CHARACTERS.map(c=>`<option value="${c.id}" ${c.id===person?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Voce del browser <select id="browser-voice"><option value="">Italiano automatico</option>${voices.map(v=>`<option value="${escapeHtml(v.voiceURI)}" ${v.voiceURI===selected?'selected':''}>${escapeHtml(v.name)}</option>`).join('')}</select></label></div><p class="notice">${voices.length?'Puoi assegnare una voce diversa a ogni personaggio.':'Nessuna voce italiana rilevata: verrà usata la voce disponibile sul dispositivo; i sottotitoli restano attivi.'} ${this.app.voiceStore.available?'':'Il browser non permette di conservare registrazioni in questa sessione.'}</p><p><b>${linesFor(person).length} battute</b> · ${linesFor(person).filter(l=>this.app.voiceStore.get(l.id)).length} registrazioni personali</p><div id="voice-feedback" role="status"></div>${linesFor(person).map(l=>`<div class="voice-line"><div><p>«${escapeHtml(l.text)}»</p><small>${l.id} · ${this.app.voiceStore.get(l.id)?'AUDIO PERSONALE':'VOCE DEL BROWSER'}</small></div><div class="buttons"><button class="small-btn" data-listen="${l.id}">▶ Ascolta</button><label class="file-label">Carica<input type="file" accept="audio/*,.m4a,.mp3,.wav,.ogg" data-upload="${l.id}" ${this.app.voiceStore.available?'':'disabled'}></label>${this.app.voiceStore.get(l.id)?`<button class="small-btn" data-remove="${l.id}">Rimuovi</button>`:''}</div></div>`).join('')}<p class="notice">${VOICE_LINES.length} battute già predisposte per la banda. Nuove frasi e pacchetti audio potranno essere aggiunti mantenendo gli stessi identificativi.</p>`;document.querySelector('#voice-person').onchange=e=>{this.app.audio.stop();this.voiceCharacter=e.target.value;this.voices();};document.querySelector('#browser-voice').onchange=e=>{this.app.settings.voices[person]=e.target.value;this.app.save.saveSettings(this.app.settings);};this.content.querySelectorAll('[data-listen]').forEach(b=>b.onclick=()=>{this.app.audio.unlock();this.app.audio.play(b.dataset.listen,{force:true});});this.content.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;try{await this.app.voiceStore.put(input.dataset.upload,file);this.voices();document.querySelector('#voice-feedback').textContent='Registrazione salvata su questo dispositivo.';}catch(e){document.querySelector('#voice-feedback').textContent=e.message;}});this.content.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{try{this.app.audio.stop();await this.app.voiceStore.remove(b.dataset.remove);this.voices();}catch{document.querySelector('#voice-feedback').textContent='Impossibile rimuovere il file in questa sessione.';}});}
 settings(){this.content.innerHTML=`<h3>Accesso alle missioni</h3><div class="setting-row"><label for="unlock-all-missions">Sblocca tutte le missioni</label><input id="unlock-all-missions" type="checkbox" aria-describedby="unlock-missions-help" ${this.app.settings.unlockAllMissions===true?'checked':''}></div><p id="unlock-missions-help" class="notice">Attiva per scegliere qualsiasi missione. Disattiva per tornare alle missioni sbloccate con i tuoi progressi. La checkbox non segna le missioni come completate e non cancella progressi o checkpoint.</p><p><b>Colonna sonora originale · 12 temi</b><br>Musica, effetti e voci sono indipendenti. Le preferenze restano salvate su questo dispositivo.</p><div class="setting-row"><label for="mute-all">Silenzia tutto</label><input id="mute-all" type="checkbox" ${this.app.settings.muted?'checked':''}></div>${[['music','Musica e fanfare','musicVolume'],['effects','Effetti sonori','effectsVolume'],['voices','Voci dei personaggi','voiceVolume']].map(([id,label,volume])=>`<div class="setting-row"><label for="${id}-enabled">${label}</label><input id="${id}-enabled" type="checkbox" ${this.app.settings[id+'Enabled']!==false?'checked':''}><label class="audio-volume-label" for="${id}-volume">Volume</label><input id="${id}-volume" type="range" min="0" max="1" step=".05" value="${this.app.settings[volume]??.65}"></div>`).join('')}<div class="setting-row"><label for="music-preview">Ascolta i temi</label><select id="music-preview">${Object.entries(TRACKS).map(([id,title])=>`<option value="${id}">${id} · ${title}</option>`).join('')}</select></div><div class="voice-controls"><button id="music-listen" class="small-btn">▶ Ascolta 15 secondi</button><button id="music-stop" class="small-btn">■ Ferma</button></div><p id="music-feedback" role="status"></p><a class="text-button" href="music.html" target="_blank" rel="noopener">ALBUM COMPLETO E DOWNLOAD WAV ↗</a><div class="setting-row"><label for="volume">Volume generale</label><input id="volume" type="range" min="0" max="1" step=".05" value="${this.app.settings.volume}"></div><div class="setting-row"><label for="frequency">Frequenza battute</label><select id="frequency"><option value="normal">Normale</option><option value="low" ${this.app.settings.frequency==='low'?'selected':''}>Ridotta</option></select></div><div class="setting-row"><label for="motion">Riduci movimento ed effetti</label><input id="motion" type="checkbox" ${this.app.settings.reduceMotion?'checked':''}></div><h3>Guida nella gara</h3><div class="setting-row"><label for="race-auto">Accelerazione automatica</label><input id="race-auto" type="checkbox" ${this.app.settings.raceAutoAccelerate!==false?'checked':''}></div><div class="setting-row"><label for="race-assist">Guida assistita</label><input id="race-assist" type="checkbox" ${this.app.settings.raceAssist!==false?'checked':''}></div><p class="notice">Gas automatico: concentrati sullo sterzo; FRENO ha sempre la precedenza. Se lo disattivi compare il pedale GAS. La guida assistita rende lo sterzo più dolce e rallenta prima delle curve; scegli tu la direzione. Entrambe le opzioni sono indipendenti dalla difficoltà e restano salvate.</p><p>Usa FULL SCREEN accanto a PAUSA per ingrandire il gioco. RIDUCI ripristina la vista normale. Ruotando lo smartphone i comandi si adattano.</p><p><b>Controlli</b><br>WASD o frecce: movimento.<br>J / Z / spazio: pugno e interazione.<br>K / X: speciale. J → J → K: conclusione combo.<br>Nel prologo: J esamina, K scatto.<br>In gara: gas automatico (disattivabile), ← → / A D sterzo, ↓ / S freno, K / X turbo. R: tieni premuto per la retromarcia. Con gas manuale, ↑ / W accelera. Su telefono: trascina lo sterzo a sinistra; FRENO e TURBO a destra. Rilascia il pollice per raddrizzare lo sterzo. RETRO è separato dal freno.<br>Q / TAB: cambio personaggio. START / Invio / ESC: pausa e opzioni. SELECT / M: diario.<br>Su touch trascina il pollice sul pad per cambiare direzione, anche in diagonale. Con l’altro pollice usa A (azione) e B (speciale). CAMBIA sceglie il personaggio, START apre la pausa, SELECT mostra gli obiettivi. Il centro del pad ferma il movimento. Vicino a un compagno KO, premi A / J per rianimarlo in 2 secondi: se vieni colpito, il soccorso si interrompe. Riparte con il 15% di vita e lo speciale pieno.</p><p class="notice">I progressi vengono salvati all’inizio di ogni capitolo. Le registrazioni vocali sono locali al browser: conserva anche gli originali.</p>${this.app.playing?'<button id="return-home" class="secondary">TORNA AL GARAGE</button>':''}`;const apply=()=>{this.app.audio.unlock();this.app.save.saveSettings(this.app.settings);this.app.music?.tick();this.app.updateSound();};
 document.querySelector('#unlock-all-missions').onchange=e=>{this.app.settings.unlockAllMissions=e.target.checked;this.app.save.saveSettings(this.app.settings);this.app.journey?.refresh();};
 for(const [id,key]of [['race-auto','raceAutoAccelerate'],['race-assist','raceAssist']])document.querySelector('#'+id).onchange=e=>{this.app.settings[key]=e.target.checked;this.app.input.clear();this.app.save.saveSettings(this.app.settings);this.app.raceControls?.syncSettings();};
 document.querySelector('#mute-all').onchange=e=>{this.app.settings.muted=e.target.checked;if(e.target.checked)this.app.audio.stop();apply();};
 for(const [id,volume]of [['music','musicVolume'],['effects','effectsVolume'],['voices','voiceVolume']]){
 document.querySelector('#'+id+'-enabled').onchange=e=>{this.app.settings[id+'Enabled']=e.target.checked;if(id==='voices')this.app.audio.stop();apply();};
 document.querySelector('#'+id+'-volume').oninput=e=>{this.app.settings[volume]=Number(e.target.value);if(id==='voices')this.app.audio.stop();apply();};}
 document.querySelector('#music-listen').onclick=()=>{const off=this.app.settings.muted||!this.app.settings.musicEnabled;document.querySelector('#music-feedback').textContent=off?'Attiva la musica e disattiva il silenziamento per ascoltare.':'Anteprima di 15 secondi.';if(!off)this.app.music?.preview(document.querySelector('#music-preview').value);};
 document.querySelector('#music-stop').onclick=()=>{this.app.music?.stopPreview();document.querySelector('#music-feedback').textContent='Anteprima fermata.';};
 document.querySelector('#volume').oninput=e=>{this.app.settings.volume=Number(e.target.value);this.app.save.saveSettings(this.app.settings);};document.querySelector('#frequency').onchange=e=>{this.app.settings.frequency=e.target.value;this.app.save.saveSettings(this.app.settings);};document.querySelector('#motion').onchange=e=>{this.app.settings.reduceMotion=e.target.checked;this.app.save.saveSettings(this.app.settings);};document.querySelector('#return-home')?.addEventListener('click',()=>{this.close();this.app.goHome();});}
}
